const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const aoi = ee.Geometry.Point([36.157, 36.206]).buffer(7000).bounds(); // Antakya approx, ~7 km buffer
    const scale = 1000;

    // Target windows (±1 day around the dates to reduce noise)
    const febStart = ee.Date('2023-02-20');
    const febEnd = ee.Date('2023-02-22').advance(1, 'day'); // end-exclusive
    const aprStart = ee.Date('2023-04-29');
    const aprEnd = ee.Date('2023-05-01').advance(1, 'day'); // end-exclusive

    // Baseline window (January 2023)
    const baseStart = ee.Date('2023-01-01');
    const baseEnd = ee.Date('2023-02-01');

    // Helpers
    async function countTotalPixels(region) {
      const total = ee.Image(1).reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9
      }).get('constant');
      return (await total.getInfo()) || 0;
    }

    async function dailyMeanNTL(start, end) {
      const colId = 'NASA/VIIRS/001/VNP46A2';
      let ic = ee.ImageCollection(colId)
        .filterDate(start, end)
        .filterBounds(aoi);
      const size = await ic.size().getInfo();
      if (size === 0) {
        return { ok: false, reason: 'empty', nImages: 0 };
      }
      // Prefer gap-filled band if present; otherwise use BRDF-corrected NTL.
      // Try both; fallback gracefully by selecting whichever exists.
      const firstBands = await ic.first().bandNames().getInfo();
      let band = null;
      if (firstBands && firstBands.indexOf('Gap_Filled_DNB_BRDF-Corrected_NTL') !== -1) {
        band = 'Gap_Filled_DNB_BRDF-Corrected_NTL';
      } else if (firstBands && firstBands.indexOf('DNB_BRDF-Corrected_NTL') !== -1) {
        band = 'DNB_BRDF-Corrected_NTL';
      } else {
        return { ok: false, reason: 'bands-missing', nImages: size };
      }
      ic = ic.select(band);
      const img = ic.mean().rename('ntl');
      // Pixel stats
      const totalPix = await countTotalPixels(aoi);
      const validCount = await img.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: scale,
        maxPixels: 1e9
      }).get('ntl').getInfo();
      const meanVal = await img.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: aoi,
        scale: scale,
        maxPixels: 1e9
      }).get('ntl').getInfo();
      const valid = (validCount || 0);
      if (valid === 0) return { ok: false, reason: 'no-valid', nImages: size, totalPix, validPix: 0 };
      return { ok: true, mean: meanVal, nImages: size, totalPix, validPix: valid, band, dataset: colId };
    }

    async function monthlyMeanNTL(monthStart) {
      const colId = 'NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG';
      const monthEnd = ee.Date(monthStart).advance(1, 'month');
      let ic = ee.ImageCollection(colId)
        .filterDate(monthStart, monthEnd)
        .filterBounds(aoi)
        .select('avg_rad');
      const size = await ic.size().getInfo();
      if (size === 0) return { ok: false, reason: 'empty', nImages: 0 };
      const img = ee.Image(ic.first()).rename('ntl');
      const totalPix = await countTotalPixels(aoi);
      const validCount = await img.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: scale,
        maxPixels: 1e9
      }).get('ntl').getInfo();
      const meanVal = await img.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: aoi,
        scale: scale,
        maxPixels: 1e9
      }).get('ntl').getInfo();
      const valid = (validCount || 0);
      if (valid === 0) return { ok: false, reason: 'no-valid', nImages: size, totalPix, validPix: 0 };
      return { ok: true, mean: meanVal, nImages: size, totalPix, validPix: valid, band: 'avg_rad', dataset: colId };
    }

    function isBad(val) {
      return val === null || val === undefined || Number.isNaN(val) || !Number.isFinite(val);
    }

    // 2. Try Daily Black Marble
    const dailyFeb = await dailyMeanNTL(febStart, febEnd);
    const dailyApr = await dailyMeanNTL(aprStart, aprEnd);
    const dailyBase = await dailyMeanNTL(baseStart, baseEnd);

    let useDaily = dailyFeb.ok && dailyApr.ok && dailyBase.ok;

    // 3. Fallback to Monthly if needed
    let feb, apr, base;
    if (useDaily) {
      feb = dailyFeb;
      apr = dailyApr;
      base = dailyBase;
      console.log(`Dataset: ${feb.dataset} (band=${feb.band})`);
      console.log(`Jan-2023 baseline (daily): Images=${dailyBase.nImages}, Pixels=${dailyBase.validPix}/${dailyBase.totalPix}, Mean=${dailyBase.mean !== null ? dailyBase.mean.toFixed(3) : 'null'}`);
      console.log(`Feb 21±1d: Images=${dailyFeb.nImages}, Pixels=${dailyFeb.validPix}/${dailyFeb.totalPix}, Mean=${dailyFeb.mean !== null ? dailyFeb.mean.toFixed(3) : 'null'}`);
      console.log(`Apr 30±1d: Images=${dailyApr.nImages}, Pixels=${dailyApr.validPix}/${dailyApr.totalPix}, Mean=${dailyApr.mean !== null ? dailyApr.mean.toFixed(3) : 'null'}`);
    } else {
      const monBase = await monthlyMeanNTL('2023-01-01');
      const monFeb = await monthlyMeanNTL('2023-02-01');
      const monApr = await monthlyMeanNTL('2023-04-01');
      if (!(monBase.ok && monFeb.ok && monApr.ok)) {
        // Determine C1 vs C2
        const anyEmpty = [dailyFeb, dailyApr, dailyBase, monBase, monFeb, monApr].some(r => r && r.ok === false && r.reason === 'empty');
        if (anyEmpty) {
          console.log(`Daily availability - Feb:${dailyFeb.nImages || 0}, Apr:${dailyApr.nImages || 0}, Base:${dailyBase.nImages || 0}`);
          console.log(`Monthly availability - Jan:${monBase.nImages || 0}, Feb:${monFeb.nImages || 0}, Apr:${monApr.nImages || 0}`);
          console.log('C1');
          return;
        }
        const anyNoValid = [dailyFeb, dailyApr, dailyBase, monBase, monFeb, monApr].some(r => r && r.ok === false && r.reason === 'no-valid');
        if (anyNoValid) {
          console.log('No valid pixels after masking.');
          console.log('C2');
          return;
        }
        console.log('Data retrieval failed.');
        console.log('D');
        return;
      }
      feb = monFeb; apr = monApr; base = monBase;
      console.log(`Dataset: ${feb.dataset} (band=${feb.band})`);
      console.log(`Jan-2023 baseline (monthly): Images=${base.nImages}, Pixels=${base.validPix}/${base.totalPix}, Mean=${!isBad(base.mean) ? base.mean.toFixed(3) : 'null'}`);
      console.log(`Feb-2023 (monthly): Images=${feb.nImages}, Pixels=${feb.validPix}/${feb.totalPix}, Mean=${!isBad(feb.mean) ? feb.mean.toFixed(3) : 'null'}`);
      console.log(`Apr-2023 (monthly): Images=${apr.nImages}, Pixels=${apr.validPix}/${apr.totalPix}, Mean=${!isBad(apr.mean) ? apr.mean.toFixed(3) : 'null'}`);
    }

    // 4. Calculation: increases relative to Jan baseline
    if (isBad(base.mean) || isBad(feb.mean) || isBad(apr.mean)) {
      console.log('Invalid statistic (null/NaN).');
      console.log('C3');
      return;
    }
    const incFeb = feb.mean - base.mean;
    const incApr = apr.mean - base.mean;

    // Validation print
    console.log(`Increase vs Jan - Feb window: ${incFeb.toFixed(3)}`);
    console.log(`Increase vs Jan - Apr window: ${incApr.toFixed(3)}`);

    // 5. Final Answer
    if (!Number.isFinite(incFeb) || !Number.isFinite(incApr)) {
      console.log('C3');
    } else if (incFeb > incApr) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (e) {
    console.log(`Error: ${e.message}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
